//! HTTP 路由（契約：docs/API.md）。邏輯都在 `mars_core::engine`，這裡只做 HTTP 包裝。

use axum::{
    Json, Router,
    extract::{Path, Query, State},
    http::{HeaderMap, HeaderValue, StatusCode, header},
    response::{IntoResponse, Response},
    routing::{get, post},
};
use mars_core::{
    engine::{Engine, EngineError, GridBytes, LayerQuery, ReplanReq, RouteReq, TrackReq},
    localize::SimRequest,
};
use serde::Deserialize;
use serde_json::Value;
use std::{path::PathBuf, sync::Arc};
use tower_http::{cors::CorsLayer, services::ServeDir};

type St = State<Arc<Engine>>;

pub fn router(st: Arc<Engine>, web_dir: Option<PathBuf>) -> Router {
    let api = Router::new()
        .route("/api/meta", get(meta))
        .route("/api/terrain", get(terrain))
        .route("/api/layer/{name}", get(layer))
        .route("/api/route", post(route))
        .route("/api/routes/compare", post(compare))
        .route("/api/replan", post(replan))
        .route("/api/localize/sim", post(localize_sim))
        .route("/api/track", post(track))
        .with_state(st)
        .layer(CorsLayer::permissive());
    match web_dir {
        Some(dir) if dir.exists() => api.fallback_service(ServeDir::new(dir)),
        _ => api,
    }
}

pub struct ApiError(EngineError);

impl From<EngineError> for ApiError {
    fn from(e: EngineError) -> Self {
        Self(e)
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let (status, _, _) = self.0.describe();
        (
            StatusCode::from_u16(status).unwrap(),
            Json(self.0.to_json()),
        )
            .into_response()
    }
}

/// 規劃工作耗 CPU，丟到 blocking 執行緒。
async fn blocking<T: Send + 'static>(f: impl FnOnce() -> T + Send + 'static) -> T {
    tokio::task::spawn_blocking(f)
        .await
        .expect("planner task panicked")
}

fn grid_response(g: GridBytes) -> Response {
    let mut hm = HeaderMap::new();
    hm.insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("application/octet-stream"),
    );
    hm.insert("x-width", HeaderValue::from(g.w));
    hm.insert("x-height", HeaderValue::from(g.h));
    hm.insert(
        "x-cell-m",
        HeaderValue::from_str(&g.cell_m.to_string()).unwrap(),
    );
    hm.insert(
        header::ACCESS_CONTROL_EXPOSE_HEADERS,
        HeaderValue::from_static("x-width, x-height, x-cell-m"),
    );
    (hm, g.bytes).into_response()
}

async fn meta(State(st): St) -> Json<Value> {
    Json(st.meta())
}

#[derive(Deserialize)]
struct StepQ {
    step: Option<usize>,
}

async fn terrain(State(st): St, Query(q): Query<StepQ>) -> Response {
    grid_response(st.terrain(q.step.unwrap_or(4)))
}

async fn layer(
    State(st): St,
    Path(name): Path<String>,
    Query(q): Query<LayerQuery>,
) -> Result<Response, ApiError> {
    Ok(grid_response(blocking(move || st.layer(&name, &q)).await?))
}

async fn route(State(st): St, Json(r): Json<RouteReq>) -> Result<Json<Value>, ApiError> {
    Ok(Json(blocking(move || st.route(&r)).await?))
}

async fn compare(State(st): St, Json(r): Json<RouteReq>) -> Result<Json<Value>, ApiError> {
    Ok(Json(blocking(move || st.compare(&r)).await?))
}

async fn replan(State(st): St, Json(r): Json<ReplanReq>) -> Result<Json<Value>, ApiError> {
    Ok(Json(blocking(move || st.replan(&r)).await?))
}

async fn localize_sim(State(st): St, Json(r): Json<SimRequest>) -> Json<Value> {
    Json(st.localize_sim(&r))
}

async fn track(State(st): St, Json(r): Json<TrackReq>) -> Result<Json<Value>, ApiError> {
    Ok(Json(st.track(&r)?))
}

#[cfg(test)]
mod tests {
    use super::*;
    use axum::body::Body;
    use axum::http::Request;
    use http_body_util::BodyExt;
    use mars_core::synth::{SynthSpec, generate};
    use serde_json::json;
    use std::sync::OnceLock;
    use tower::ServiceExt;

    fn app() -> Router {
        static ST: OnceLock<Arc<Engine>> = OnceLock::new();
        let st = ST
            .get_or_init(|| Arc::new(Engine::new(generate(&SynthSpec::default()))))
            .clone();
        router(st, None)
    }

    async fn send(req: Request<Body>) -> (StatusCode, HeaderMap, Vec<u8>) {
        let res = app().oneshot(req).await.unwrap();
        let (status, headers) = (res.status(), res.headers().clone());
        (
            status,
            headers,
            res.into_body().collect().await.unwrap().to_bytes().to_vec(),
        )
    }

    async fn get_raw(uri: &str) -> (StatusCode, HeaderMap, Vec<u8>) {
        send(Request::get(uri).body(Body::empty()).unwrap()).await
    }

    async fn post_json(uri: &str, body: Value) -> (StatusCode, Value) {
        let req = Request::post(uri)
            .header("content-type", "application/json")
            .body(Body::from(body.to_string()))
            .unwrap();
        let (s, _, b) = send(req).await;
        (s, serde_json::from_slice(&b).unwrap())
    }

    async fn meta_json() -> Value {
        serde_json::from_slice(&get_raw("/api/meta").await.2).unwrap()
    }

    #[tokio::test]
    async fn meta_shape() {
        let v = meta_json().await;
        assert_eq!(v["width"], 1024);
        assert!(!v["targets"].as_array().unwrap().is_empty());
        assert!(v["beacons"].as_array().unwrap().len() >= 5);
        assert!(v["params"]["nav"]["uwb"]["sigma_m"].is_number());
    }

    #[tokio::test]
    async fn binary_layers_match_headers() {
        for uri in [
            "/api/terrain?step=4",
            "/api/layer/slope?step=4",
            "/api/layer/hazard?step=4",
            "/api/layer/cost?mode=safe&step=4",
            "/api/layer/pnr?step=4&o2_min=200",
            "/api/layer/coverage?step=4",
        ] {
            let (s, h, b) = get_raw(uri).await;
            assert_eq!(s, StatusCode::OK, "{uri}");
            let w: usize = h["x-width"].to_str().unwrap().parse().unwrap();
            let hh: usize = h["x-height"].to_str().unwrap().parse().unwrap();
            let bpp = if uri.starts_with("/api/terrain") {
                4
            } else {
                1
            };
            assert_eq!(b.len(), w * hh * bpp, "{uri}");
        }
        let (s, _, b) = get_raw("/api/layer/nope").await;
        assert_eq!(s, StatusCode::NOT_FOUND);
        let v: Value = serde_json::from_slice(&b).unwrap();
        assert_eq!(v["error"], "unknown_layer");
    }

    #[tokio::test]
    async fn route_compare_replan_localize_track() {
        let m = meta_json().await;
        let (base, t) = (m["base"].clone(), &m["targets"][0]);
        let goal = json!([t["x"], t["y"]]);

        let (s, r) = post_json(
            "/api/route",
            json!({"start": base, "goal": goal, "mode": "safe"}),
        )
        .await;
        assert_eq!(s, StatusCode::OK);
        assert!(r["path"].as_array().unwrap().len() >= 2);

        let (s, c) = post_json("/api/routes/compare", json!({"start": base, "goal": goal})).await;
        assert_eq!(s, StatusCode::OK);
        for k in ["safe", "balanced", "science"] {
            assert!(c[k]["length_m"].is_number(), "{k}");
        }

        let (s, rp) = post_json(
            "/api/replan",
            json!({"pos": base, "goal": goal, "mode": "safe", "o2_min": 35}),
        )
        .await;
        assert_eq!(s, StatusCode::OK);
        assert_eq!(rp["must_return"], true);

        let (s, loc) = post_json("/api/localize/sim", json!({"true_pos": base, "seed": 7})).await;
        assert_eq!(s, StatusCode::OK);
        assert_eq!(loc["simulated"], true);
        assert!(loc["sigma_m"].is_number());
        assert!(loc["visible_beacons"].as_array().unwrap().len() >= 2);

        let (s, tr) = post_json(
            "/api/track",
            json!({"pos": base, "sigma_m": 2.0, "path": r["path"]}),
        )
        .await;
        assert_eq!(s, StatusCode::OK);
        assert_eq!(tr["status"], "on_route");

        let (s, e) = post_json("/api/route", json!({"start": [-5, 0], "goal": goal})).await;
        assert_eq!(s, StatusCode::BAD_REQUEST);
        assert_eq!(e["error"], "out_of_bounds");
    }
}
